NEW_FILES = {'src/language/lexico.py': '"""parche-98: LEXICO (sinonimos, antonimos, hiperonimos) a partir de data/lexico_es.json (MCR espanol CC BY 3.0 + Princeton WordNet; ver data/LEXICO_LICENCIA.txt).\nSi el fichero no esta, todo devuelve vacio y el resto del modelo funciona igual (se puede retirar borrandolo). Es una AYUDA de ultimo recurso: la memoria manda."""\nimport json\nimport os\nimport re\nimport unicodedata\n\n_F = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "data", "lexico_es.json")\n_D = None\n\n\ndef nrm(w):\n    w = unicodedata.normalize("NFD", w.lower())\n    return "".join(c for c in w if unicodedata.category(c) != "Mn").strip()\n\n\ndef st(w):\n    w = nrm(w)\n    return re.sub(r"(os|as|es|o|a|e|s)$", "", w) if len(w) > 3 else w\n\n\ndef _load():\n    global _D\n    if _D is None:\n        _D = {"ok": False, "idx": {}, "syn": [], "pos": [], "hyp": {}, "ant": {}, "known": set()}\n        try:\n            d = json.load(open(_F, encoding="utf-8"))\n        except (OSError, ValueError):\n            return _D\n        _D["syn"] = {int(k): v for k, v in d["syn"].items()}\n        _D["pos"] = {int(k): v for k, v in d["pos"].items()}\n        _D["hyp"] = {int(k): v for k, v in d["hyp"].items()}\n        _D["ant"] = {int(k): v for k, v in d["ant"].items()}\n        idx = {}\n        for i, lems in _D["syn"].items():\n            for lem in lems:\n                k = st(lem) if " " not in lem else nrm(lem)\n                idx.setdefault(k, []).append(i)\n                _D["known"].add(nrm(lem))\n        _D["idx"], _D["ok"] = idx, True\n    return _D\n\n\ndef disponible():\n    return _load()["ok"]\n\n\ndef conoce(w):\n    """True si la palabra (sin tilde) es un lema del lexico: sirve para NO tomarla por errata."""\n    return nrm(w) in _load()["known"]\n\n\ndef sentidos(w):\n    d = _load()\n    return d["idx"].get(st(w), [])\n\n\ndef sinonimos(w, pos=None):\n    """Lemas que comparten algun sentido con w (sin w), en orden de aparicion. pos: \'n\',\'v\',\'a\',\'r\' o None."""\n    d, out = _load(), []\n    for i in sentidos(w):\n        if pos and d["pos"].get(i) != pos:\n            continue\n        for lem in d["syn"].get(i, []):\n            if st(lem) != st(w) and lem not in out:\n                out.append(lem)\n    return out\n\n\ndef antonimos(w):\n    d, out = _load(), []\n    for i in sentidos(w):\n        for j in d["ant"].get(i, []):\n            for lem in d["syn"].get(j, []):\n                if lem not in out:\n                    out.append(lem)\n    return out\n\n\ndef hiperonimos(w, niveles=1):\n    """Lemas de los hiperonimos (categorias mas generales); con niveles>1 sube por la jerarquia."""\n    d, out, cur = _load(), [], set(sentidos(w))\n    seen = set(cur)\n    for _ in range(niveles):\n        nxt = set()\n        for i in cur:\n            for j in d["hyp"].get(i, []):\n                if j not in seen:\n                    seen.add(j)\n                    nxt.add(j)\n                    for lem in d["syn"].get(j, [])[:2]:\n                        if lem not in out:\n                            out.append(lem)\n        cur = nxt\n    return out\n\n\ndef es_un_tipo_de(a, b, max_niv=6):\n    """True si b esta por encima de a en la jerarquia de hiperonimos (un gato es un animal)."""\n    d = _load()\n    objetivo = set(sentidos(b))\n    cur, seen = set(sentidos(a)), set()\n    for _ in range(max_niv):\n        if cur & objetivo:\n            return True\n        seen |= cur\n        cur = {j for i in cur for j in d["hyp"].get(i, [])} - seen\n        if not cur:\n            return False\n    return bool(cur & objetivo)\n\n\n# ---- preguntas sobre palabras (ultimo recurso: la memoria manda) -----------------------------------------------------\ndef _lista(xs, n=6):\n    xs = [x for x in xs if " " not in x][:n] or xs[:n]\n    return xs[0] if len(xs) == 1 else ", ".join(xs[:-1]) + " y " + xs[-1]\n\n\ndef _nombre_pos(w):\n    """Sentidos de w que son sustantivos (para definir) o, si no hay, cualquiera."""\n    d = _load()\n    ss = sentidos(w)\n    return [i for i in ss if d["pos"].get(i) == "n"] or ss\n\n\ndef responder(raw):\n    """Contesta preguntas sobre PALABRAS con el lexico. Devuelve None si no aplica o no sabe."""\n    if not disponible():\n        return None\n    t = re.sub(r"\\s+", " ", re.sub(r"[¡!¿?.,;:]", " ", nrm(raw))).strip()\n    def orig(w):\n        mm = next((x for x in re.findall(r"[A-Za-zÁÉÍÓÚáéíóúñÑüÜ]+", raw) if nrm(x) == w), None)\n        return mm or w\n\n    m = re.match(r"(?:cual es |cuales son |dime |dame )?(?:el |los |un |algun )?(?:sinonimos?|palabras? (?:parecidas?|equivalentes?)) (?:de |a |para )(?:la palabra )?(.+)$", t) \\\n        or re.match(r"(?:dime |dame |que |cual )?(?:otra|otras) palabras? (?:hay |existe |puedo usar |se puede usar )?(?:para|por|de) (?:la palabra )?(.+)$", t) \\\n        or re.match(r"como se dice (.+) de otra (?:forma|manera)$", t) or re.match(r"que palabra significa (?:lo mismo que|igual que) (.+)$", t)\n    if m:\n        w = m.group(1).strip().split()[-1] if len(m.group(1).split()) <= 3 else None\n        if w:\n            r = sinonimos(w)\n            if r:\n                return f"Según el léxico, otras palabras para «{orig(w)}»: {_lista(r)}."\n        return None\n    m = re.match(r"(?:cual es |cuales son |dime |dame )?(?:el |los |un |algun )?(?:antonimos?|opuestos?|contrarios?) (?:de |a )(?:la palabra )?(.+)$", t) \\\n        or re.match(r"(?:cual es )?lo (?:contrario|opuesto) (?:de|a) (.+)$", t) or re.match(r"que palabra significa lo contrario (?:de|que) (.+)$", t)\n    if m and len(m.group(1).split()) <= 3:\n        w = m.group(1).split()[-1]\n        r = antonimos(w)\n        if r:\n            return f"Según el léxico, lo contrario de «{orig(w)}» es {_lista(r, 3)}."\n        return None\n    m = re.match(r"es (?:un |una |el |la )?(\\w+) (?:un |una |el |la )?(?:tipo de |clase de )?(\\w+)$", t)\n    if m and not any(x[:1].isupper() for x in re.findall(r"[A-Za-zÁÉÍÓÚáéíóúñÑ]+", raw)[1:3]) and conoce(m.group(1)) and conoce(m.group(2)) and m.group(1) != m.group(2) and es_un_tipo_de(m.group(1), m.group(2)):\n        return f"Según el léxico, sí: «{orig(m.group(1))}» es un tipo de «{orig(m.group(2))}» (según el sentido de la palabra)."\n    m = re.match(r"que (?:es|son) (?:un |una |el |la |los |las )?(\\w+)$", t)\n    if m and conoce(m.group(1)) and not (re.findall(r"[A-Za-zÁÉÍÓÚáéíóúñÑ]+", raw) or [""])[-1][:1].isupper():\n        w = m.group(1)\n        ss = _nombre_pos(w)\n        h = []\n        for i in ss:\n            h = [x for j in _load()["hyp"].get(i, []) for x in _load()["syn"].get(j, [])[:2]]\n            if h:\n                break\n        s_ = [x for x in sinonimos(w, "n") if " " not in x] if ss else []\n        if h:\n            return f"Según el léxico, «{orig(w)}» es un tipo de {_lista(h, 3)}." + (f" Otras palabras: {_lista(s_, 4)}." if s_ else "")\n        if s_:\n            return f"Según el léxico, «{orig(w)}» significa lo mismo que {_lista(s_, 4)}."\n    return None\n', 'scripts/construir_lexico.py': '"""Construye data/lexico_es.json (sinonimos, antonimos, hiperonimos) a partir de datos abiertos:\n  - Multilingual Central Repository (MCR) espanol, via Open Multilingual WordNet 1.4 (CC BY 3.0, http://adimen.si.ehu.es/web/MCR/)\n  - Princeton WordNet 3.0 (relaciones entre sentidos; licencia WordNet, https://wordnet.princeton.edu/license-and-commercial-use)\nUso: python -m scripts.construir_lexico <carpeta omw-1.4> <carpeta wordnet>   (las dos carpetas salen de nltk_data: corpora/omw-1.4 y corpora/wordnet)"""\nimport json\nimport os\nimport re\nimport sys\nimport unicodedata\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n\n\ndef nrm(w):\n    w = unicodedata.normalize("NFD", w.lower().replace("_", " "))\n    return "".join(c for c in w if unicodedata.category(c) != "Mn").strip()\n\n\ndef main(omw, wn):\n    spa = {}\n    for ln in open(os.path.join(omw, "mcr", "wn-data-spa.tab"), encoding="utf-8"):\n        if ln.startswith("#") or "\\t" not in ln:\n            continue\n        sid, typ, lem = (ln.rstrip("\\n").split("\\t") + ["", "", ""])[:3]\n        if typ == "lemma" and lem:\n            spa.setdefault(sid, [])\n            lem = lem.replace("_", " ")\n            if lem not in spa[sid]:\n                spa[sid].append(lem)\n    hyp, ant = {}, {}\n    for pos in ("noun", "verb", "adj", "adv"):\n        for ln in open(os.path.join(wn, "data." + pos), encoding="latin-1"):\n            if ln.startswith("  "):\n                continue\n            p = ln.split(" ")\n            off, ss = p[0], p[2].replace("s", "a")\n            sid = f"{off}-{ss}"\n            nw = int(p[3], 16)\n            i = 4 + 2 * nw\n            for k in range(int(p[i])):\n                sym, o2, pos2, _st = p[i + 1 + 4 * k:i + 5 + 4 * k]\n                tid = f"{o2}-{pos2.replace(\'s\', \'a\')}"\n                if sym in ("@", "@i"):\n                    hyp.setdefault(sid, []).append(tid)\n                elif sym == "!":\n                    ant.setdefault(sid, []).append(tid)\n    allids = sorted(set(spa) | set(hyp) | set(ant) | {t for v in hyp.values() for t in v} | {t for v in ant.values() for t in v})\n    num = {s_: i for i, s_ in enumerate(allids)}\n    out = {"v": 2, "fuente": "MCR spa (CC BY 3.0) + Princeton WordNet 3.0", "n": len(allids),\n           "syn": {str(num[s_]): v for s_, v in spa.items()}, "pos": {str(num[s_]): s_[-1] for s_ in spa},\n           "hyp": {str(num[s_]): [num[t] for t in v] for s_, v in hyp.items()},\n           "ant": {str(num[s_]): [num[t] for t in v] for s_, v in ant.items() if s_ in spa and any(t in spa for t in v)}}\n    out["ant"] = {k: [j for j in v if allids[j] in spa] for k, v in out["ant"].items()}\n    dst = os.path.join(ROOT, "data", "lexico_es.json")\n    json.dump(out, open(dst, "w", encoding="utf-8"), ensure_ascii=False, separators=(",", ":"))\n    ids = allids\n    print(f"lexico: {len(spa)} sentidos con lemma espanol, {len(out[\'hyp\'])} con hiperonimo, {len(out[\'ant\'])} con antonimo -> {dst} ({os.path.getsize(dst) // 1024} KB)")\n\n\nif __name__ == "__main__":\n    main(sys.argv[1], sys.argv[2])\n', 'data/LEXICO_LICENCIA.txt': '\n   \t\t  ------------------------------------------\n    \t\t  Multilingual Central Respository (MCR) 3.0\n    \t\t  ------------------------------------------\n\n  The contents of this package are distributed under different open licenses. \nIf you want to redistribute this software, part of it, or derived works based \non it or on any of its parts, make sure you are doing so under the terms stated\nin the license applying to each of the involved modules.\n\n  The licenses applying to the modules contained in MCR are the following:\n\n 1.- English WordNet synset and relation data, contained in folder engWN/ are \n     distributed under the original WordNet license. You can find it at \n     http://wordnet.princeton.edu/wordnet/license\n\n 2.- All other data in this package are distributed under Attribution 3.0 Unported\n     (CC BY 3.0) license. You can find it at \n     http://creativecommons.org/licenses/by/3.0/\n\n---\nlexico_es.json se construye con scripts/construir_lexico.py a partir de:\n * Multilingual Central Repository (MCR), espanol - CC BY 3.0 - http://adimen.si.ehu.es/web/MCR/ (distribuido en Open Multilingual WordNet 1.4)\n * Princeton WordNet 3.0 (relaciones entre sentidos) - https://wordnet.princeton.edu/license-and-commercial-use\nAtribucion obligatoria. Para retirarlo del modelo basta borrar data/lexico_es.json.\n', 'data/textos/sistema_solar_examen6.tsv': '# Examen 6 (parche-97): formas GENERALES de preguntar (contar, listar, definir, tag questions, existencia, seguimiento, comparar). Informativo.\nSEMILLA: fabrica\nU: El Sol es una estrella.\t\nU: El Sol está en el centro del Sistema Solar.\t\nU: Los planetas giran alrededor del Sol.\t\nU: Mercurio es el planeta más cercano al Sol.\t\nU: Venus es el segundo planeta.\t\nU: La Tierra es el tercer planeta y tiene una luna.\t\nU: La Luna gira alrededor de la Tierra.\t\nU: Marte es un planeta rojo.\t\nU: Marte tiene dos lunas.\t\nU: Júpiter es el planeta más grande.\t\nU: Júpiter es un gigante gaseoso.\t\nU: Saturno tiene anillos.\t\nU: Urano y Neptuno son planetas helados.\t\nU: Plutón es un planeta enano.\t\nU: Los asteroides son rocas pequeñas.\t\nU: Los cometas están hechos de hielo y polvo.\t\nU: El Sistema Solar es el conjunto de planetas, asteroides, cometas y lunas que orbitan alrededor del Sol.\t\nU: cuenta los planetas que existen en el sistema solar\t8\nU: puedes contar el numero de planetas que existen en el sistema solar?\t8\nU: dime el número de lunas que tiene Marte\tdos\nU: ¿Podrías decirme cuántos planetas hay?\t8\nU: Marte es rojo, ¿verdad?\tSí\nU: ¿Es verdad que Marte es rojo?\tSí\nU: ¿Es cierto que Júpiter es el planeta más grande?\tSí\nU: Dime si es verdad que Saturno tiene anillos\tSí\nU: ¿Verdad que la Tierra tiene una luna?\tSí\nU: Necesito que me digas qué es el Sol\testrella\nU: Quiero que me expliques qué es un cometa\thielo\nU: ¿Qué significa Plutón?\tenano\nU: Definición de cometa\thielo\nU: ¿Qué entiendes por asteroide?\troca\nU: Dime todo lo que sepas de Marte\trojo\nU: Cuéntame todo sobre la Tierra\tluna\nU: Muéstrame lo que sabes de Marte\trojo\nU: Lista los planetas\tMercurio\nU: Dame una lista de los planetas\tVenus\nU: Dime el nombre de los planetas\tNeptuno\nU: ¿Cómo se llaman los planetas?\tTierra\nU: Enséñame los planetas que conoces\tUrano\nU: ¿Existen planetas helados?\tUrano\nU: ¿Hay algún planeta rojo?\tMarte\nU: ¿Existe algún planeta con anillos?\tSaturno\nU: ¿Conoces algún planeta rojo?\tMarte\nU: ¿Conoces el planeta Marte?\trojo\nU: ¿Has oído hablar de Plutón?\tenano\nU: ¿Cuántas lunas tiene Marte?\tdos\nU: ¿Y la Tierra?\tuna\nU: Compara Marte y la Tierra\trojo\nU: ¿Cuál es la diferencia entre Marte y la Tierra?\tluna\nU: ¿Cuál es mayor: Júpiter o Marte?\tJúpiter\nU: ¿Cuál es más grande, Marte o Júpiter?\tJúpiter\nU: cual es el planeta mas lejano al sol?\tNo lo sé\nU: Por favor, dime cuántas lunas tiene Marte\tdos\nU: Dime por favor cuántas lunas tiene Marte\tdos\nU: ¿Puedes decirme de qué color es Marte?\trojo\nU: ¿Sabrías decirme cuántas lunas tiene Marte?\tdos\nU: Me puedes explicar qué son los asteroides\trocas\n', 'data/textos/sistema_solar_examen7.tsv': '# Examen 7 (parche-98): LEXICO: sinonimos/antonimos/tipo de y palabras que no conoce pero la memoria si por sinonimo. Informativo.\nSEMILLA: fabrica\nU: El Sol es una estrella.\t\nU: El Sol está en el centro del Sistema Solar.\t\nU: Los planetas giran alrededor del Sol.\t\nU: Mercurio es el planeta más cercano al Sol.\t\nU: Venus es el segundo planeta.\t\nU: La Tierra es el tercer planeta y tiene una luna.\t\nU: La Luna gira alrededor de la Tierra.\t\nU: Marte es un planeta rojo.\t\nU: Marte tiene dos lunas.\t\nU: Júpiter es el planeta más grande.\t\nU: Júpiter es un gigante gaseoso.\t\nU: Saturno tiene anillos.\t\nU: Urano y Neptuno son planetas helados.\t\nU: Plutón es un planeta enano.\t\nU: Los asteroides son rocas pequeñas.\t\nU: Los cometas están hechos de hielo y polvo.\t\nU: El Sistema Solar es el conjunto de planetas, asteroides, cometas y lunas que orbitan alrededor del Sol.\t\nU: ¿Es Plutón un planeta diminuto?\tenano\nU: ¿Qué planeta es el más próximo al Sol?\tMercurio\nU: ¿Cuál es el planeta más próximo al Sol?\tMercurio\nU: ¿Qué planeta está más próximo al Sol?\tMercurio\nU: ¿Cuál es el sinónimo de rápido?\tveloz\nU: ¿Cuál es el antónimo de grande?\tpequeño\nU: ¿Cuál es lo contrario de comprar?\tvender\nU: Dime otra palabra para comprar\tadquirir\nU: ¿Es un gato un animal?\tSegún el léxico\nU: ¿Es un coche un vehículo?\tSegún el léxico\nU: ¿Qué es un perro?\tcánido\nU: ¿Qué es una silla?\tasiento\nU: ¿Qué sinónimos tiene coche?\tautomóvil\nU: Dame un sinónimo de coche\tauto\nU: ¿Qué palabra significa lo contrario de vender?\tcomprar\nU: ¿Qué es Marte?\trojo\n', 'tests/test_parche98.py': '"""parche-98: lexico (sinonimos, antonimos, tipo de) y sinonimos conocidos por la memoria."""\nimport pytest\n\nfrom src.language import consultas, lexico\n\npytestmark = pytest.mark.skipif(not lexico.disponible(), reason="falta data/lexico_es.json")\n\n\ndef test_sinonimos_antonimos():\n    assert "auto" in lexico.sinonimos("coche")\n    assert "pequeño" in lexico.antonimos("grande")\n    assert "vender" in lexico.antonimos("comprar")\n\n\ndef test_tipo_de():\n    assert lexico.es_un_tipo_de("gato", "animal")\n    assert not lexico.es_un_tipo_de("gato", "piedra")\n\n\ndef test_responder_palabras():\n    assert "veloz" in lexico.responder("¿Cuál es el sinónimo de rápido?")\n    assert "vender" in lexico.responder("¿Cuál es lo contrario de comprar?")\n    assert lexico.responder("¿Qué es Marte?") is None          # nombres propios: no se inventa un sentido\n    assert lexico.responder("¿Es Marte un planeta?") is None\n\n\ndef test_sinonimizar_usa_la_memoria():\n    class M:\n        facts = [{"s": "PLUTON", "p": "SER", "o": "ENANO"}]\n        display = {}\n    assert "enano" in consultas.sinonimizar("¿Es Plutón diminuto?", M())\n    assert consultas.sinonimizar("¿Es Plutón enano?", M()) == "¿Es Plutón enano?"\n    assert consultas.SUBS and consultas.SUBS[-1][0].lower() == "diminuto"\n\n\ndef test_no_corrige_palabras_del_lexico():\n    class M:\n        facts = []\n        display = {}\n    assert consultas.corregir("¿Qué es un caballo?", M()) == "¿Qué es un caballo?"\n\n\ndef test_canonical_lexico():\n    assert consultas.canonical("Dime otra palabra para comprar") == "¿Dime otra palabra para comprar?"\n    assert consultas.canonical("¿Qué sinónimos tiene coche?") == "¿Cuál es el sinónimos de coche?"\n    assert consultas.canonical("¿Qué planeta está más próximo al Sol?") == "¿Cuál es el planeta más cercano al Sol?"\n'}
BLOB = ''
NEW_FILES["data/lexico_es.json"] = zlib.decompress(base64.b64decode(BLOB)).decode("utf-8")

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-98 instalado. Copias en {bk}" if plan else "parche-98: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

